from iSpy import units

ROOT = Path(__file__).resolve().parents[1]
ROBOTPOSE = ROOT / "iSpy" / "web" / "static" / "js" / "robotpose.js"


class UnitPackResolutionTests(unittest.TestCase):
    def test_builtin_packs_are_loaded(self):
        keys = {pack["key"] for pack in units.list_unit_packs()}
        self.assertTrue({"frc", "metric", "imperial"}.issubset(keys))

    def test_resolves_by_key_alias_and_unit_name(self):
        cases = {
            "frc": "frc",
            "wpilib": "frc",
            "metric": "metric",
            "m": "metric",
            "meters": "metric",
            "centimeter": "metric",
            "imperial": "imperial",
            "inch": "imperial",
            "feet": "imperial",
        }
        for name, expected in cases.items():
            with self.subTest(name=name):
                pack = units.resolve_unit_pack(name)
                self.assertIsNotNone(pack)
                self.assertEqual(pack["key"], expected)

    def test_unknown_unit_returns_none(self):
        self.assertIsNone(units.resolve_unit_pack("furlong"))

    def test_missing_metadata_is_derived(self):
        raw = {
            "key": "tiny",
            "input_unit": "inch",
            "output_unit": "inch",
            "input_to_inches": 1.0,
            "inches_to_output": 1.0,
        }
        pack = units._normalize_pack(raw, "tiny")
        self.assertEqual(pack["labels"]["input"], "in")
        self.assertEqual(pack["labels"]["output"], "in")
        self.assertEqual(pack["labels"]["speed"], "in/s")
        self.assertEqual(pack["viewer"]["robot_to_viewer"], ["x", "z", "-y"])
        self.assertEqual(pack["viewer"]["camera"]["far"], 200.0)
        self.assertEqual(pack["viewer"]["bounds"]["z"], {"min": 0.0, "max": 10.0})


class UnitConversionTests(unittest.TestCase):
    def test_input_and_output_factors(self):
        self.assertAlmostEqual(units.input_to_inches("frc"), 1.0)
        self.assertAlmostEqual(units.input_to_inches("meter"), 1.0 / 0.0254)
        self.assertAlmostEqual(units.inches_to_output("frc"), 0.0254)
        self.assertAlmostEqual(units.inches_to_output("imperial"), 1.0)

    def test_meters_to_output_is_unit_aware(self):
        self.assertAlmostEqual(units.meters_to_output("frc"), 1.0)
        self.assertAlmostEqual(units.meters_to_output("metric"), 1.0)
        self.assertAlmostEqual(units.meters_to_output("imperial"), 1.0 / 0.0254)

    def test_legacy_config_helpers_use_packs(self):
        from iSpy.config.iSpyConfig import unit_label, unit_to_inches, unit_to_output

        for unit in ("meter", "meters", "inch", "inches", "foot", "feet", "centimeter"):
            with self.subTest(unit=unit):
                self.assertAlmostEqual(unit_to_output(2.0, unit), 2.0)

        self.assertAlmostEqual(unit_to_inches(2.0, "centimeter"), 2.0 / 0.0254)
        self.assertAlmostEqual(unit_to_inches(2.0, "foot"), 2.0)
        self.assertEqual(unit_label("frc"), "in")
        self.assertEqual(unit_label("imperial"), "in")

    def test_output_point_applies_scale_and_axis_signs(self):
        pack = units._normalize_pack(
            {
                "key": "_axis_test",
                "input_unit": "inch",
                "output_unit": "inch",
                "input_to_inches": 1.0,
                "inches_to_output": 1.0,
                "axis": {
                    "x": -1.0,
                    "y": 1.0,
                    "z": -1.0,
                    "roll": 1.0,
                    "pitch": 1.0,
                    "yaw": 1.0,
                },
            },
            "_axis_test",
        )
        units._PACKS["_axis_test"] = pack
        try:
            point = units.output_point_from_inches((1.0, 2.0, 3.0), "_axis_test")
            self.assertEqual(point, (-1.0, 2.0, -3.0))
        finally:
            units._PACKS.pop("_axis_test", None)

    def test_invalid_axis_map_falls_back(self):
        pack = units._normalize_pack(
            {
                "key": "_bad_axis",
                "input_to_inches": 1.0,
                "inches_to_output": 1.0,
                "viewer": {"robot_to_viewer": ["x", "y", "-z"]},
            },
            "_bad_axis",
        )
        self.assertEqual(pack["viewer"]["robot_to_viewer"], ["x", "z", "-y"])


class ViewerSettingsTests(unittest.TestCase):
    def test_frc_viewer_defaults(self):
        viewer = units.viewer_settings("frc")
        self.assertEqual(viewer["robot_to_viewer"], ["x", "z", "-y"])
        self.assertEqual(viewer["output_label"], "m")
        self.assertEqual(viewer["camera"]["position"], [9.0, 9.0, 9.0])
        self.assertEqual(viewer["camera"]["far"], 200.0)
        self.assertEqual(viewer["fog_density"], 0.04)
        self.assertEqual(viewer["axes_size"], 8.0)
        self.assertEqual(viewer["grid"]["extent"], 20.0)
        self.assertEqual(viewer["bounds_viewer"]["y"], {"min": 0.0, "max": 5.0})
        self.assertEqual(viewer["bounds_viewer"]["z"], {"min": -10.0, "max": 10.0})

    def test_imperial_viewer_uses_large_bounds(self):
        viewer = units.viewer_settings("imperial")
        self.assertEqual(viewer["output_label"], "in")
        self.assertEqual(viewer["camera"]["position"], [350.0, 350.0, 350.0])
        self.assertEqual(viewer["camera"]["far"], 5000.0)
        self.assertEqual(viewer["fog_density"], 0.001)
        self.assertEqual(viewer["axes_size"], 320.0)
        self.assertEqual(viewer["grid"]["extent"], 800.0)
        self.assertEqual(viewer["grid"]["marker_size"], 10.0)
        self.assertEqual(viewer["bounds_viewer"]["y"], {"min": 0.0, "max": 200.0})

    def test_grid_extent_is_derived_when_omitted(self):
        raw = {
            "key": "_no_grid",
            "input_to_inches": 1.0,
            "inches_to_output": 1.0,
            "viewer": {"grid": {"divisions": 10, "marker_size": 0.5}},
        }
        pack = units._normalize_pack(raw, "_no_grid")
        units._PACKS["_no_grid"] = pack
        try:
            viewer = units.viewer_settings("_no_grid")
            self.assertEqual(viewer["grid"]["divisions"], 10)
            self.assertGreater(viewer["grid"]["extent"], 0)
        finally:
            units._PACKS.pop("_no_grid", None)

    def test_default_camera_pitch_is_level(self):
        for name in ("frc", "metric", "imperial"):
            with self.subTest(name=name):
                self.assertEqual(units.unit_default_camera_pitch(name), 0.0)


class UnitValidationTests(unittest.TestCase):
    def test_valid_pack_has_no_errors(self):
        pack = {
            "key": "custom",
            "input_unit": "inch",
            "output_unit": "meter",
            "input_to_inches": 1.0,
            "inches_to_output": 0.0254,
            "viewer": {"robot_to_viewer": ["x", "z", "-y"]},
        }
        self.assertEqual(units.validate_unit_pack(pack), [])

    def test_missing_and_bad_fields_are_reported(self):
        errors = units.validate_unit_pack(
            {
                "input_to_inches": 0,
                "inches_to_output": -1,
                "axis": {"x": "left"},
                "viewer": {
                    "robot_to_viewer": ["x", "y", "-z"],
                    "bounds": [],
                    "camera": [],
                    "fog_density": -1,
                    "axes_size": 0,
                },
            }
        )
        joined = " | ".join(errors)
        self.assertIn("missing key", joined)
        self.assertIn("input_to_inches must be positive", joined)
        self.assertIn("inches_to_output must be positive", joined)
        self.assertIn("axis.x must be a number", joined)
        self.assertIn("determinant +1", joined)
        self.assertIn("viewer.bounds must be an object", joined)
        self.assertIn("viewer.camera must be an object", joined)
        self.assertIn("viewer.fog_density must be >= 0", joined)
        self.assertIn("viewer.axes_size must be positive", joined)


def _node_available() -> bool:
    return shutil.which("node") is not None


@unittest.skipUnless(_node_available(), "node is required for JS math tests")
class RobotPoseAxisMapTests(unittest.TestCase):
    def _run(self, script: str, arg=None):
        with tempfile.TemporaryDirectory() as tmp:
            mjs = Path(tmp) / "robotpose.mjs"
            mjs.write_bytes(ROBOTPOSE.read_bytes())
            prefix = (
                "import { axisMapMatrix, robotToViewer, robotToViewerQuat } "
                f"from 'file:///{mjs.as_posix()}';"
            )
            cmd = ["node", "--input-type=module", "--eval", prefix + script]
            if arg is not None:
                cmd.append(json.dumps(arg))
            out = subprocess.run(cmd, capture_output=True, text=True, check=True)
            return json.loads(out.stdout)

    def test_default_position_mapping(self):
        self.assertEqual(self._run("console.log(JSON.stringify(robotToViewer(1,2,3)));"), [1, 3, -2])

    def test_custom_position_mapping(self):
        result = self._run(
            "console.log(JSON.stringify(robotToViewer(1,2,3,['x','-z','y'])));"
        )
        self.assertEqual(result, [1, -3, 2])

    def test_invalid_mappings_fall_back(self):
        for bad in (["x", "y", "-z"], ["x", "y"], ["q", "y", "z"]):
            with self.subTest(bad=bad):
                result = self._run(
                    "const m=axisMapMatrix(JSON.parse(process.argv[1]));"
                    "console.log(JSON.stringify(m));",
                    bad,
                )
                self.assertEqual(result, [1, 0, 0, 0, 0, 1, 0, -1, 0])

    def test_quaternion_keeps_historical_default(self):
        # Existing viewer behavior: the identity orientation maps robot +Y to
        # viewer +Z and +Z to -Y.
        result = self._run(
            "console.log(JSON.stringify(robotToViewerQuat(0,0,0)));"
        )
        x, y, z, w = result
        self.assertAlmostEqual(x, math.sqrt(0.5), places=6)
        self.assertAlmostEqual(y, 0.0, places=6)
        self.assertAlmostEqual(z, 0.0, places=6)
        self.assertAlmostEqual(w, math.sqrt(0.5), places=6)


class UnitPackJsonTests(unittest.TestCase):
    def test_shipped_json_matches_normalized_pack(self):
        for name in ("frc", "metric", "imperial"):
            path = ROOT / "Units" / f"{name}.json"
            data = json.loads(path.read_text(encoding="utf-8"))
            pack = units.resolve_unit_pack(name)
            self.assertIsNotNone(pack)
            self.assertEqual(pack["key"], data["key"])
            self.assertAlmostEqual(
                pack["input_to_inches"], data["input_to_inches"], places=12
            )
            self.assertAlmostEqual(
                pack["inches_to_output"], data["inches_to_output"], places=12
            )
            self.assertEqual(pack["labels"], data["labels"])
            self.assertEqual(pack["viewer"]["robot_to_viewer"], data["viewer"]["robot_to_viewer"])
            self.assertEqual(pack["viewer"]["fog_density"], data["viewer"]["fog_density"])
            self.assertEqual(pack["viewer"]["axes_size"], data["viewer"]["axes_size"])

    def test_readme_documents_every_top_level_key(self):
        text = (ROOT / "Units" / "README.md").read_text(encoding="utf-8")
        for key in (
            "schema_version",
            "key",
            "input_unit",
            "output_unit",
            "input_to_inches",
            "inches_to_output",
            "aliases",
            "axis",
            "labels",
            "defaults",
            "viewer",
            "robot_to_viewer",
            "bounds",
            "scale",
            "grid",
            "camera",
        ):
            self.assertIn(key, text)
